  const NC = 500; const cp = new Float32Array(NC * 3), cc = new Float32Array(NC * 3), cv = []; const cols = [[0.95, 0.63, 0.23], [0.9, 0.34, 0.29], [0.44, 0.75, 0.55], [0.44, 0.66, 0.77], [1, 1, 1]]; for (let i = 0; i < NC; i++) { cp[i * 3] = -24 + Math.random() * 50; cp[i * 3 + 1] = Math.random() * 12; cp[i * 3 + 2] = (Math.random() - 0.5) * 12; const c = cols[i % 5]; cc.set(c, i * 3); cv.push(0.8 + Math.random() * 1.4); } const cg = new THREE.BufferGeometry(); cg.setAttribute('position', new THREE.BufferAttribute(cp, 3)); cg.setAttribute('color', new THREE.BufferAttribute(cc, 3)); scene.add(new THREE.Points(cg, new THREE.PointsMaterial({ size: 0.16, vertexColors: true })));
